create table public.personal_competency_surveys (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, personal_development_profile_id uuid not null references public.personal_development_profiles(id) on delete cascade, personal_role_profile_id uuid not null references public.personal_role_profiles(id) on delete cascade, title text not null, intro_message text, thank_you_message text, status text not null default 'draft' check (status in ('draft','active','closed')), created_by_profile_id uuid references public.profiles(id) on delete set null, launched_at timestamptz, closed_at timestamptz, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()));
create table public.personal_competency_survey_recipients (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, survey_id uuid not null references public.personal_competency_surveys(id) on delete cascade, recipient_name text not null, recipient_email text not null, recipient_title text, relationship_to_role text, access_token text not null unique default (replace(gen_random_uuid()::text,'-','') || replace(gen_random_uuid()::text,'-','')), status text not null default 'pending' check (status in ('pending','opened','completed')), invited_at timestamptz, opened_at timestamptz, completed_at timestamptz, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), unique(survey_id,recipient_email));
create table public.personal_competency_survey_responses (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, survey_id uuid not null references public.personal_competency_surveys(id) on delete cascade, recipient_id uuid not null unique references public.personal_competency_survey_recipients(id) on delete cascade, response_json jsonb not null default '{}'::jsonb, normalized_competencies jsonb not null default '[]'::jsonb, submitted_at timestamptz not null default timezone('utc',now()), created_at timestamptz not null default timezone('utc',now()));
create index personal_competency_surveys_profile_idx on public.personal_competency_surveys(personal_development_profile_id,created_at desc);
create index personal_competency_survey_recipients_survey_idx on public.personal_competency_survey_recipients(survey_id,created_at desc);
create trigger set_updated_at_personal_competency_surveys before update on public.personal_competency_surveys for each row execute function public.set_updated_at();
create trigger set_updated_at_personal_competency_survey_recipients before update on public.personal_competency_survey_recipients for each row execute function public.set_updated_at();
alter table public.personal_competency_surveys enable row level security;
alter table public.personal_competency_survey_recipients enable row level security;
alter table public.personal_competency_survey_responses enable row level security;
create policy "personal_competency_surveys_manage" on public.personal_competency_surveys for all to authenticated using (organization_id=public.current_profile_organization_id() and exists(select 1 from public.personal_development_profiles p where p.id=personal_competency_surveys.personal_development_profile_id and (p.profile_id in(select id from public.profiles where auth_user_id=auth.uid()) or public.current_app_role() in('system_admin','hospital_admin','mentor')))) with check (organization_id=public.current_profile_organization_id() and exists(select 1 from public.personal_development_profiles p where p.id=personal_competency_surveys.personal_development_profile_id and (p.profile_id in(select id from public.profiles where auth_user_id=auth.uid()) or public.current_app_role() in('system_admin','hospital_admin','mentor'))));
create policy "personal_competency_survey_recipients_manage" on public.personal_competency_survey_recipients for all to authenticated using (organization_id=public.current_profile_organization_id() and exists(select 1 from public.personal_competency_surveys s join public.personal_development_profiles p on p.id=s.personal_development_profile_id where s.id=personal_competency_survey_recipients.survey_id and (p.profile_id in(select id from public.profiles where auth_user_id=auth.uid()) or public.current_app_role() in('system_admin','hospital_admin','mentor')))) with check (organization_id=public.current_profile_organization_id() and exists(select 1 from public.personal_competency_surveys s join public.personal_development_profiles p on p.id=s.personal_development_profile_id where s.id=personal_competency_survey_recipients.survey_id and (p.profile_id in(select id from public.profiles where auth_user_id=auth.uid()) or public.current_app_role() in('system_admin','hospital_admin','mentor'))));
create policy "personal_competency_survey_responses_manage" on public.personal_competency_survey_responses for all to authenticated using (organization_id=public.current_profile_organization_id() and exists(select 1 from public.personal_competency_surveys s join public.personal_development_profiles p on p.id=s.personal_development_profile_id where s.id=personal_competency_survey_responses.survey_id and (p.profile_id in(select id from public.profiles where auth_user_id=auth.uid()) or public.current_app_role() in('system_admin','hospital_admin','mentor')))) with check (organization_id=public.current_profile_organization_id() and exists(select 1 from public.personal_competency_surveys s join public.personal_development_profiles p on p.id=s.personal_development_profile_id where s.id=personal_competency_survey_responses.survey_id and (p.profile_id in(select id from public.profiles where auth_user_id=auth.uid()) or public.current_app_role() in('system_admin','hospital_admin','mentor'))));
